import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";
import {
  distinctCustomRoles,
  normalizeRole,
  type RoleUsage,
} from "@/lib/roles";

// Internal only: callers authenticate and supply the session owner ID.
export async function readRoleUsage(
  userId: string,
  tx: Prisma.TransactionClient = db,
): Promise<RoleUsage> {
  const [user, contacts] = await Promise.all([
    tx.user.findUniqueOrThrow({
      where: { id: userId },
      select: { preferredRoles: true },
    }),
    tx.contact.findMany({
      where: { userId, archivedAt: null },
      select: { id: true, name: true, jobRole: true },
      orderBy: [{ name: "asc" }, { id: "asc" }],
    }),
  ]);
  const roles = new Map<string, RoleUsage["contactRoles"][number]>();
  for (const contact of contacts) {
    if (!contact.jobRole?.trim()) continue;
    const key = normalizeRole(contact.jobRole);
    const entry = roles.get(key);
    const identity = { id: contact.id, name: contact.name };
    if (entry) {
      entry.count++;
      entry.contacts.push(identity);
    } else {
      roles.set(key, {
        title: contact.jobRole.trim(),
        count: 1,
        contacts: [identity],
      });
    }
  }
  return { shortcuts: user.preferredRoles, contactRoles: [...roles.values()] };
}

export async function listCustomRoles(
  userId: string,
  tx: Prisma.TransactionClient = db,
): Promise<string[]> {
  const usage = await readRoleUsage(userId, tx);
  return distinctCustomRoles([
    ...usage.shortcuts,
    ...usage.contactRoles.map(({ title }) => title),
  ]);
}
